/*
 * A262775  For a(n+1), sift out all numbers congruent to a(n-1) mod a(n)
 *          except for a(n-1); a(0)=0, a(1)=2.
 * https://oeis.org/A262775
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0)=0, a(1)=2; for n>1, a(n) is the smallest integer k​>​a(n‑1)
 *            such that k % a(j) != a(j‑1) for all 1 ≤ j < n. (The seq. is
 *            generated by a sift‐type sieve similar to the Eratosthenes
 *            sieve.)
 * Range:     u8 n <= 43, u16 n <= 812, u32 n <= 812, u64 n <= 812,
 *            u128 n <= 812, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

static seq_t *seq = NULL;
static idx_t seq_cap = 0;
static idx_t seq_len = 0;

/* Ensure that the array can hold at least `need` elements. */
static void ensure_cache(idx_t need)
{
    if (seq_cap >= need) return;
    idx_t new_cap = seq_cap ? seq_cap * 2 : 4;
    if (new_cap < need) new_cap = need;
    seq_t *p = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    if (!p) abort();
    seq = p;
    seq_cap = new_cap;
}

seq_t a(idx_t n)
{
    if (seq_len == 0) {          /* first call – initialise with a(0)=0, a(1)=2 */
        ensure_cache(2);
        seq[0] = (seq_t)0;
        seq[1] = (seq_t)2;
        seq_len = 2;
    }

    while (seq_len <= n) {
        /* Prepare space for the new term. */
        ensure_cache(seq_len + 1);

        idx_t j = seq_len;               /* index of the term to compute */
        seq_t cand = seq[seq_len - 1] + (seq_t)1;   /* start above previous term */

        /* Find the smallest admissible candidate. */
        while (1) {
            bool ok = true;
            for (idx_t k = 1; k < j; ++k) {          /* check against all earlier mods */
                if (cand % seq[k] == seq[k - 1]) {
                    ok = false;
                    break;
                }
            }
            if (ok) break;   /* candidate accepted */
            cand = cand + (seq_t)1;   /* try next integer */
        }

        seq[j] = cand;
        seq_len = j + 1;   /* we have now filled indices 0..j */
    }

    return seq[n];
}
